programs.haiku:
"""Logic-word lexicon: how strongly the current token is a word of pushback, negation,
hedged condition, or conclusion. Predicts the neuron as a weighted sum of those group flags."""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Words that push back on or qualify the preceding claim
CONTRAST = {"but", "however", "though", "yet", "wait", "actually", "unless", "although",
            "still", "instead", "except", "only", "even", "whereas"}
# Negation and impossibility
NEGATION = {"not", "cannot", "no", "never", "impossible", "undefined", "unable", "nor",
            "without", "none", "neither", "nothing", "n't", "’t", "'t"}
# Hedged conditions and modals
MODAL = {"can", "could", "would", "should", "might", "may", "must", "maybe", "perhaps",
         "whether", "if", "since", "because", "when"}
# Words that draw a conclusion
CONCLUDE = {"therefore", "thus", "so", "hence", "consequently", "finally"}

WEIGHTS = ((CONTRAST, 0.55), (NEGATION, 0.25), (MODAL, 0.2), (CONCLUDE, -0.3))


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    value = -0.03
    for words, weight in WEIGHTS:
        if word in words:
            value += weight
    return carry, value

"""Layer 15, MLP hidden unit 3140, read by one down_proj component (p-82af68dd).

What the component is: its activation is mostly that single hidden unit (about 0.6 of
the read direction's norm 0.9) plus a diffuse remainder. The unit depends on context,
not on the current word: a token's identity explains only a few percent of it.

The clearest pattern is about what a word attaches to, judged by the word just before:
- a preposition ("of", "in", "for", "from") right after a noun, as in "the debate [on]",
  is pushed negative;
- a participle ("driven", "used", "based") right after a noun, as in "a truck [driven]
  by", is pushed more negative;
- a preposition right after a verb, as in "sent [to]", is pushed positive;
- punctuation right after a noun, as in "the file[,]", is pushed slightly positive.
Everywhere else the program predicts 0. The values are the mean activation of each case.

This explains about 1% of the variance. The rest is spread over many contexts the
word-class rules cannot see.
"""

PREPOSITIONS = {
    "of", "in", "on", "at", "for", "with", "from", "to", "by", "behind", "under",
    "about", "into", "through", "over", "between", "among", "near", "around", "after",
    "before", "during", "without", "within", "across", "along", "against",
}
NOUN_BEFORE = {"prep": -0.23, "participle": -0.39, "punct": 0.09}  # the word before is a noun
VERB_BEFORE = {"prep": 0.28}  # the word before is a verb


def kind(text):
    """Rough word class of one token: 'prep', 'participle', 'noun', 'verb', 'punct' or 'other'."""
    from wordnet import parts_of_speech

    w = text.strip().lower()
    if not any(ch.isalpha() for ch in w):
        return "punct"
    if w in PREPOSITIONS:
        return "prep"
    if not w.isalpha():
        return "other"
    if len(w) > 4 and w.endswith(("ed", "ing")):
        return "participle"
    parts = parts_of_speech(w)
    if "noun" in parts:
        return "noun"
    if "verb" in parts:
        return "verb"
    return "other"


READS = ()


def step(carry, prefix, upstream):
    """The activation at the newest token, from its word class and the word class just before it."""
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    cur = kind(prefix.token_strings[-1])
    before = kind(prefix.token_strings[-2])
    if before == "noun" and cur in NOUN_BEFORE:
        return carry, NOUN_BEFORE[cur]
    if before == "verb" and cur in VERB_BEFORE:
        return carry, VERB_BEFORE[cur]
    return carry, 0.0

"""Layer 15 MLP unit 3142 (down_proj component 3142): a dominance / predicate-role detector.

In plain terms, the unit is:
- positive on words of dominance, superiority and primacy ("dominant", "sole", "primary",
  "best", "most", "winner", "instead", "preferred");
- more positive on a word of importance or fitness that follows a copula or a role verb
  ("is responsible", "was better", "became the first", "is essential", "is the main");
- positive on "the" in general, and most on "the" right after "is", "became", "was",
  "won";
- negative on negation and loss words ("not", "n't", "nicht", "avoided", "prevented",
  "decreased", "lose");
- more negative on exclusion words right after a copula ("is not", "was only", "is just",
  "was excluded", "is simply");
- negative on "the" that opens a subordinate clause ("although the", "until the",
  "that the").

Everything else sits near zero. The program reads only the current token and the one
before it, with no memory. It is a word-level approximation: it explains a small share
of the variance (the big spikes depend on the wider sentence, which a word list
cannot see).
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Dominance, superiority and primacy.
DOMINANCE = {
    "dominate", "dominates", "dominant", "dominated", "dominance", "sole", "only",
    "primary", "biggest", "largest", "fastest", "winner", "winners", "win", "wins", "won",
    "champion", "superior", "best", "most", "greatest", "first", "lead", "leading",
    "crucial", "essential", "important", "responsible", "responsibility", "preferred",
    "preference", "instead", "rather", "favourite", "favorite", "takes", "took",
    "majority", "alone", "highest", "strongest", "priority", "better", "bigger",
    "greater", "top", "main", "key", "supreme", "ultimate", "chief", "foremost",
    "prime", "paramount",
}

# Words of importance, fitness or selection, that read well as a predicate ("is ___").
FITNESS = {
    "responsible", "better", "sufficient", "larger", "enough", "critical", "essential",
    "crucial", "important", "necessary", "required", "needed", "suitable", "appropriate",
    "best", "chosen", "selected", "recommended", "useful", "correct", "valid", "eligible",
    "common", "higher", "greater", "smaller", "easier", "most", "first", "more", "what",
    "where", "deemed", "used", "accepted", "the", "one", "lone", "main", "primary",
    "instead", "only",
}

# Negation, prevention, loss and decrease.
NEGATION = {
    "not", "no", "never", "nicht", "kein", "avoided", "prevented", "prevent", "ceased",
    "excluded", "eliminated", "suppressed", "decreased", "decreases", "decrease", "fell",
    "falling", "drops", "drop", "lose", "lost", "loses", "missed", "irrelevant",
    "useless", "negligible", "insufficient", "prohibited", "fails", "failed",
    "failure", "rare", "false", "lowered", "withdrawn", "reduced", "reduce",
    "cannot", "n't",
}

# Exclusion and removal words that read as a predicate after a copula
# ("is just", "was removed").
EXCLUSION = {
    "excluded", "blocked", "simply", "just", "only", "down", "ignored", "removed", "lost",
    "reduced", "wrong", "false", "incorrect", "not", "nothing", "affected", "out",
    "separated", "safe", "okay",
}

# Copulas and verbs of becoming, winning or taking a role.
COPULAS = {
    "is", "was", "were", "are", "be", "been", "being", "am", "become", "becomes",
    "became", "becoming", "remains", "remain", "as", "named", "won", "win", "wins",
    "took", "take", "takes", "taking", "receive", "receives", "received",
}

# Words that open a subordinate clause.
SUBORDINATORS = {
    "although", "though", "until", "whether", "beyond", "despite", "while", "before",
    "since", "that", "if", "about", "because", "when", "but",
}


def _word(token: str) -> str:
    return token.strip().lower().replace("’", "'")


def step(carry, prefix, upstream: Mapping):
    """Activation at this position: a signed score for the current word in its context."""
    word = _word(prefix.token_strings[-1])
    same_doc = (len(prefix.document_ids) > 1
                and prefix.document_ids[-2] == prefix.document_ids[-1])
    before = _word(prefix.token_strings[-2]) if same_doc else ""

    value = 0.06
    if word in DOMINANCE:
        value += 0.80
    if word in NEGATION:
        value -= 0.13
    if before in COPULAS:
        value += 0.20
        if word in FITNESS or word in DOMINANCE:
            value += 1.89
        if word in EXCLUSION:
            value -= 0.78
    if word == "the":
        value += 0.12
        if before in SUBORDINATORS:
            value -= 0.31
    return carry, float(value)

"""Layer 15 MLP unit 3150 (component 3150 of layers.15.mlp.down_proj), as a number-and-entity detector.

What it responds to, in plain terms: the model is writing a number, or is about to write one, or is
about to name a specific thing (a person, place, taxon). Its strongest responses are on the blank space
that comes right before a number after a preposition or article ("... at [ ]1990", "... of [ ]2"), and on
the first digit of a number in parentheses, as in a citation "(2011)". Digits in numbers are mildly
positive, punctuation inside a number ("2.2", "1/2") is positive too, and capitalized words are slightly
positive. Lowercase words and most other punctuation are near zero. Digits right after an operator, as in
equations, are weaker.

The sample fit is rough: these token-context classes explain only about 2 to 3 percent of the activation
variance. Most of the unit's swings inside numbers and on ordinary words depend on wider context that a
token rule cannot see, so this is a sketch of its main tendencies, not a full account.
"""

READS = ()

# words after which a number or a named thing often comes next
LEAD_WORDS = {"at", "of", "to", "is", "was", "in", "by", "from", "for", "than", "about", "around",
              "until", "on", "with", "over", "under", "the", "a", "and", "or"}
OPERATORS = {"=", " =", "+", " +", "*", "^", "-", " -"}
PUNCT_IN_NUMBER = {".", "/", "-", ":"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    now = tokens[-1]
    same_doc = len(tokens) > 1 and docs[-2] == docs[-1]
    before = tokens[-2] if same_doc else ""
    word = now.strip()
    if now == " ":
        value = 2.1 if before.strip() in LEAD_WORDS else 0.65
    elif word.isdigit():
        if before in (" (", "("):
            value = 0.55
        elif before == " ":
            value = 0.47
        elif before.strip().isdigit():
            value = 0.21
        elif before in OPERATORS:
            value = 0.12
        else:
            value = 0.19
    elif now in PUNCT_IN_NUMBER and before.strip().isdigit():
        value = 0.58
    elif word[:1].isupper() and now.startswith(" "):
        value = 0.11
    else:
        value = 0.0
    return carry, value

"""Component layers.15.mlp.down_proj:3158, the "other / the rest" feature.

What it responds to: words that point at other members of a set, or at what is
left over. The core word is "other" (also "otherwise", "else", "others", "another"),
and the same idea in other languages ("autres", "других", "andere", "otros", "其他").
It also fires on words for a whole or a remainder ("overall", "general", "entire",
"whole", "total", "rest", "remainder", "remaining", "whatever") and on "etc", and on
"of" in "the rest of".

It is strongest when "other" or "otherwise" closes a list of alternatives:
"cash, securities or other", "and other", "any other", "or otherwise", "something
else". It is weak in "each other", "the other side", and in code "} else {".

The program is a lookup on the current word and the word before it. It predicts a
typical activation for each case, and 0 for every other token. Most of the
component's variance is small, token-to-token noise that no word list captures, so
the program explains only a small share of it.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Words that point at other members of a set. "else", "another" and "others" are
# weaker than "other" when they are not after a list-opening word.
OTHER_WORDS = {"other", "others", "otherwise", "else", "another"}
WEAK_OTHER_WORDS = {"else", "another", "others"}
# The same idea in other languages ("autres", "других", "andere", "其他").
OTHER_FOREIGN = {
    "其他", "其它", "другие", "других", "другими", "другой", "другая",
    "autres", "autre", "andere", "anderen", "otros", "otras", "altri", "altre",
    "outros", "sonst", "inne", "muut",
}
# Words that open a list of alternatives, or a non-specific "anything/something".
ALTERNATIVE_LEADS = {
    "or", "and", "any", "many", "all", "for", "of",
    "anything", "something", "anyone", "everyone",
}
# Words for the whole or the remainder of something.
WHOLE_OR_REST = {
    "overall", "general", "generally", "entire", "whole", "total",
    "rest", "remainder", "remaining", "whatever",
}
# Words that stand for "and so on" or "elsewhere".
AND_SO_ON = {"etc", "elsewhere", "等"}
# Quantifiers, which only weakly point at other members.
QUANTIFIERS = {"all", "any", "every", "anything", "anyone", "everything"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""

    if word in OTHER_FOREIGN:
        return carry, 4.0
    if word in OTHER_WORDS:
        if before in ALTERNATIVE_LEADS:
            return carry, 8.0  # "X or other", "any other", "something else"
        if before in {"each", "the"}:
            return carry, 1.0  # "each other", "the other side"
        if word in WEAK_OTHER_WORDS:
            return carry, 1.0  # mostly "} else {" and "others" in running text
        return carry, 2.5
    if before in OTHER_WORDS or before in OTHER_FOREIGN:
        return carry, 1.5  # the word after "other": "other provisions", "other relevant"
    if word in WHOLE_OR_REST:
        return carry, 2.0
    if word in AND_SO_ON:
        return carry, 1.5
    if word == "of" and before in {"rest", "remainder"}:
        return carry, 7.0  # "the rest of"
    if word in QUANTIFIERS:
        return carry, 0.6
    return carry, 0.0

"""Layer-15 MLP component 3181 (down_proj): a weak, mostly diffuse signal.

What it does, in plain terms: its activation is almost always small noise (about +/-0.4).
Its largest negative excursions come on words that signal something is inevitable,
obvious or expected: "of course", "always", "inevitably", "usual(ly)", "obviously",
"naturally", "understandable", "当然", "难免". It is mildly positive on the opening of a
sentence such as "This is", "That's", "It's", "这是", and on "just". Every other position
is predicted as 0. Such word rules explain almost none of the variance: token identity
alone explains about 2%, and the rest is spread thinly over the context.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Words of inevitability or obviousness: the component goes clearly negative on them.
INEVITABLE = {
    "always", "course", "inevitably", "inevitable", "obviously", "naturally",
    "usually", "usual", "understandable", "regardless", "certainly", "当然", "难免",
}
# "This/That/It" followed by "is" or "'s": a mild positive.
COPULA = {"is", "'s", "are", "是"}
SUBJECT = {"this", "that", "it", "这", "那"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower().replace("’", "'")
    if word in INEVITABLE:
        return carry, -0.9
    if word in ("这是", "just"):
        return carry, 0.33
    if word in COPULA and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip().lower() in SUBJECT:
            return carry, 0.33
    return carry, 0.0

"""Comparison-phrase feature of layers.15.mlp.down_proj component 3185.

What it does: a sparse, signed feature that fires on the words that build
comparisons and on a few function words inside formal "such/same/manner"
phrases. It is positive on the word that closes a comparison ("than", "as" in
"as big as", and the foreign equivalents "wie", "als", "comme", "como", "как"),
and negative on the word that opens one ("more", "less", "much", "same", "such"),
on the first "as" of a negated or copular comparison ("not as", "is as"), on
"of" after a partitive noun ("kind of", "part of", "amount of"), and on "and",
"of", "to" inside a "such ..." or "same manner" phrase. Everything else is
about zero. It explains only a small share of the variance.
"""

READS = ()

OPENERS = {" more", " less", " much", " same", " fewer", " greater", " such"}
CLOSERS = {" than", " wie", " als", " comme", " como", " чем", " как", " som", " jak", " như"}
NEGATORS = {" not", " nearly", " is", " are", " was", " were", " be", " been", " isn", " aren", " wasn", " nowhere", " near", " quite"}
DEGREE = {" as", " same", " such", " so", " much", " many", " more", " less", " fewer", " than"}
PARTITIVE = {" kind", " sort", " type", " types", " part", " parts", " amount", " portion", " piece", " level", " quantity", " ways", " mode", " shares", " species"}
MANNER = {" such", " same", " manner", " kind"}
FUNCTION = {" and", " of", " to", " in", " or"}


def recent(prefix, k):
    """Tokens among the k before the newest one, within the same document."""
    t = len(prefix.token_strings) - 1
    doc = prefix.document_ids[t]
    return [prefix.token_strings[j] for j in range(max(0, t - k), t) if prefix.document_ids[j] == doc]


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = recent(prefix, 1)
    near = recent(prefix, 8)
    value = -0.06
    if cur == " as":
        if prev and prev[-1] in NEGATORS:
            value += -2.2
        elif prev and prev[-1] in DEGREE:
            value += 0.75
        elif any(w in DEGREE for w in recent(prefix, 6)):
            value += 1.9
    if cur in CLOSERS:
        value += 1.3
    if cur in OPENERS:
        value += -0.55
    if cur == " of" and prev and prev[-1] in PARTITIVE:
        value += -0.94
    if cur in FUNCTION and any(w in MANNER for w in near):
        value += -0.58
    return carry, value

"""Closing marks: the token that ends an open bracket, quotation or markup span.

Component 3196 of layers.15.mlp.down_proj fires on the token that closes a span of text:
  - a ")" that ends a parenthetical (strongest when the parenthetical is short, like "(A)",
    "(1)" or "(ITA)"; weaker for long ones, and weakest when no "(" is open);
  - a closing curly or CJK quote or bracket (” 」 』 》 】 ） »), which fires most;
  - a straight quote " or ' that ends a quotation (after a word, not after a space), a
    closing "]", "}", backtick, "$" (end of maths), ">" (end of a tag), "|".
It stays near zero on opening marks ( "(", "[", "“", a quote with a leading space ' "') and
on ordinary words and punctuation. A closing mark that ends a line ("\n" in the same
token) fires much less, and one followed by more punctuation (`",`, `":`, `).`) a bit less.

Predicting the activation: the program keeps, per document, the positions of unmatched "("
(reset at each new document). It needs only the newest token and that stack.
"""

READS = ()

# Typical activation on a token that closes a span, by its closing mark.
CLOSING_MARK = {
    "」": 13, "』": 12, "》": 11, "”": 15, "】": 10, "»": 8, "）": 7, "〉": 12,
    '"': 9, "'": 4, "’": 5, "]": 6, "}": 5, "`": 6, "$": 5, ">": 4, "|": 2,
}
# A ")" with no open "(" in its document (an unmatched one) is weaker.
UNMATCHED_PAREN = 2.6


def paren_strength(tokens_inside):
    """How strongly a ")" fires, by how many tokens its parenthetical held."""
    if tokens_inside <= 3:
        return 6.5
    if tokens_inside < 10:
        return 4.3
    return 3.5


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = [doc, []]  # the document id, and positions of the unmatched "(" so far
    opens = carry[1]
    if "(" in tok and ")" not in tok:
        opens.append(prefix.position)
        return carry, 0.0
    if tok.startswith("<|"):  # special tokens such as <|im_end|>
        return carry, 0.0
    core = tok.rstrip(",.:;")  # the token without trailing punctuation
    if ")" in tok:
        if opens:
            value = paren_strength(prefix.position - opens.pop() - 1)
        else:
            value = UNMATCHED_PAREN
    else:
        value = float(CLOSING_MARK.get(core, 0.0))
    if core != tok and "\n" not in tok:
        value *= 0.6  # followed by more punctuation, like '",' or '":'
    if "\n" in tok:
        value *= 0.25  # a closing mark that ends a line fires much less
    return carry, value
